import{_ as e,o as t,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"项目范围与验收标准","description":"把 Agent 项目的业务目标、用户任务、自动化边界、交付范围和质量要求组织成可验证的项目契约。","frontmatter":{"title":"项目范围与验收标准","description":"把 Agent 项目的业务目标、用户任务、自动化边界、交付范围和质量要求组织成可验证的项目契约。","verified_at":"2026-08-01","source":["https://www.iso.org/standard/72089.html","https://www.nist.gov/itl/ai-risk-management-framework","https://www.sei.cmu.edu/library/quality-attribute-workshop-qaw-third-edition/"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/delivery-evolution/project-scope-acceptance.md","filePath":"py-agent/architecture/delivery-evolution/project-scope-acceptance.md","lastUpdated":1786083160000}'),l={name:"py-agent/architecture/delivery-evolution/project-scope-acceptance.md"};function i(s,a,o,h,p,d){return t(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="项目范围与验收标准" tabindex="-1">项目范围与验收标准 <a class="header-anchor" href="#项目范围与验收标准" aria-label="Permalink to &quot;项目范围与验收标准&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 项目最常见的交付风险，不是模型完全不能回答，而是各方对“完成”的理解不同：业务期待自动解决问题，开发只证明模型能运行，安全团队关心越权，运营团队却没有人工接管能力。范围与验收标准要把这些期望变成一份共同、可测试的项目契约。</p><p>本章关注如何形成交付基线，不重复“需求、约束与质量属性”的概念说明，也不展开某个项目的具体实现。</p><p>开始前先用<a href="/py-agent/architecture/system-architecture/requirements-constraints-quality-attributes">需求、约束与质量属性</a>形成架构输入；验收数据集、指标和实验的实现方法见<a href="/py-agent/quality/agent-evaluation/">Agent 评测</a>。本章负责把这些内容组织成项目各方共同批准的范围和完成定义。</p><h2 id="_1-项目契约" tabindex="-1">1. 项目契约 <a class="header-anchor" href="#_1-项目契约" aria-label="Permalink to &quot;1. 项目契约&quot;">​</a></h2><h3 id="_1-1-契约回答的问题" tabindex="-1">1.1 契约回答的问题 <a class="header-anchor" href="#_1-1-契约回答的问题" aria-label="Permalink to &quot;1.1 契约回答的问题&quot;">​</a></h3><p>一份完整范围契约应回答：</p><ul><li>为哪些用户解决什么任务；</li><li>哪些输入、数据和外部系统在范围内；</li><li>Agent 能建议、起草还是直接执行；</li><li>哪些失败必须拒绝、转人工或降级；</li><li>用什么数据和阈值判断交付完成；</li><li>谁对结果、安全、数据和运营负责。</li></ul><p>它不是法律合同，但应成为产品、工程、质量、安全和运营共同确认的交付基线。</p><h3 id="_1-2-输出物" tabindex="-1">1.2 输出物 <a class="header-anchor" href="#_1-2-输出物" aria-label="Permalink to &quot;1.2 输出物&quot;">​</a></h3><p>最小产物包括项目简报、范围表、用户任务清单、验收矩阵、评测数据集版本、风险登记、责任矩阵和变更记录。只有演示视频或产品原型，不能证明范围已达成。</p><h2 id="_2-业务结果" tabindex="-1">2. 业务结果 <a class="header-anchor" href="#_2-业务结果" aria-label="Permalink to &quot;2. 业务结果&quot;">​</a></h2><h3 id="_2-1-问题而非技术" tabindex="-1">2.1 问题而非技术 <a class="header-anchor" href="#_2-1-问题而非技术" aria-label="Permalink to &quot;2.1 问题而非技术&quot;">​</a></h3><p>先描述当前流程的损失和用户结果，例如“售后专员平均需要 12 分钟核对订单与政策”，而不是“建设一个基于 LangGraph 的 Agent”。框架是候选方案，不是项目目标。</p><h3 id="_2-2-结果指标" tabindex="-1">2.2 结果指标 <a class="header-anchor" href="#_2-2-结果指标" aria-label="Permalink to &quot;2.2 结果指标&quot;">​</a></h3><p>业务指标可以包括任务完成率、处理时间、一次解决率、人工接管、错误返工和每成功任务成本。消息数、模型调用数和页面访问量通常只是活动指标。</p><h3 id="_2-3-基线" tabindex="-1">2.3 基线 <a class="header-anchor" href="#_2-3-基线" aria-label="Permalink to &quot;2.3 基线&quot;">​</a></h3><p>记录当前人工流程或旧系统在相同任务上的数据。没有基线，就无法判断新 Agent 是改进还是仅增加了新界面。</p><h3 id="_2-4-反目标" tabindex="-1">2.4 反目标 <a class="header-anchor" href="#_2-4-反目标" aria-label="Permalink to &quot;2.4 反目标&quot;">​</a></h3><p>明确项目不追求什么。例如第一阶段不自动退款、不替代法务意见、不处理海外订单。反目标能阻止范围在开发过程中无边界扩张。</p><h2 id="_3-用户与任务范围" tabindex="-1">3. 用户与任务范围 <a class="header-anchor" href="#_3-用户与任务范围" aria-label="Permalink to &quot;3. 用户与任务范围&quot;">​</a></h2><h3 id="_3-1-用户角色" tabindex="-1">3.1 用户角色 <a class="header-anchor" href="#_3-1-用户角色" aria-label="Permalink to &quot;3.1 用户角色&quot;">​</a></h3><p>区分发起人、数据主体、审批人、结果消费者、运营人员和管理员。角色决定身份、数据、工具和人工控制，不应用一个“用户”概括。</p><h3 id="_3-2-任务目录" tabindex="-1">3.2 任务目录 <a class="header-anchor" href="#_3-2-任务目录" aria-label="Permalink to &quot;3.2 任务目录&quot;">​</a></h3><p>为每项任务记录触发、输入、期望产物、权威事实、允许工具、完成状态和风险等级：</p><table tabindex="0"><thead><tr><th>任务</th><th>输入</th><th>完成证据</th><th>自动化等级</th></tr></thead><tbody><tr><td>查询退款政策</td><td>问题、地区</td><td>带有效政策引用的回答</td><td>自动回答</td></tr><tr><td>生成退款建议</td><td>订单、原因</td><td>建议、依据、风险</td><td>自动草稿</td></tr><tr><td>创建退款</td><td>已确认参数</td><td>业务系统操作 ID</td><td>人工确认后执行</td></tr></tbody></table><h3 id="_3-3-任务-slice" tabindex="-1">3.3 任务 Slice <a class="header-anchor" href="#_3-3-任务-slice" aria-label="Permalink to &quot;3.3 任务 Slice&quot;">​</a></h3><p>按语言、地区、渠道、输入长度、客户等级、风险、工具路径和数据新鲜度拆分。整体成功率不能掩盖高风险 Slice 的失败。</p><h3 id="_3-4-边界输入" tabindex="-1">3.4 边界输入 <a class="header-anchor" href="#_3-4-边界输入" aria-label="Permalink to &quot;3.4 边界输入&quot;">​</a></h3><p>把模糊、冲突、缺失、恶意、超长、重复和权限不足输入纳入范围表，而不是只描述正常案例。</p><h2 id="_4-自动化边界" tabindex="-1">4. 自动化边界 <a class="header-anchor" href="#_4-自动化边界" aria-label="Permalink to &quot;4. 自动化边界&quot;">​</a></h2><h3 id="_4-1-建议" tabindex="-1">4.1 建议 <a class="header-anchor" href="#_4-1-建议" aria-label="Permalink to &quot;4.1 建议&quot;">​</a></h3><p>Agent 只提供内容或建议，用户自行决定。仍需正确性、引用和隐私验收。</p><h3 id="_4-2-草稿" tabindex="-1">4.2 草稿 <a class="header-anchor" href="#_4-2-草稿" aria-label="Permalink to &quot;4.2 草稿&quot;">​</a></h3><p>Agent 创建可编辑产物，不向外部系统提交。适合早期阶段验证质量与交互。</p><h3 id="_4-3-确认后执行" tabindex="-1">4.3 确认后执行 <a class="header-anchor" href="#_4-3-确认后执行" aria-label="Permalink to &quot;4.3 确认后执行&quot;">​</a></h3><p>Agent 提出结构化动作，服务端校验权限和业务条件，用户确认后执行。确认绑定具体参数。</p><h3 id="_4-4-受限自动执行" tabindex="-1">4.4 受限自动执行 <a class="header-anchor" href="#_4-4-受限自动执行" aria-label="Permalink to &quot;4.4 受限自动执行&quot;">​</a></h3><p>仅在低风险、可逆、范围明确且可检测条件下自动执行，并设置金额、次数、资源和时间预算。</p><h3 id="_4-5-禁止能力" tabindex="-1">4.5 禁止能力 <a class="header-anchor" href="#_4-5-禁止能力" aria-label="Permalink to &quot;4.5 禁止能力&quot;">​</a></h3><p>列出不可授予的权限和数据，例如任意 Shell、跨租户检索、通用写数据库或未经确认的外发。禁止项不应通过人工按钮临时绕过。</p><h2 id="_5-范围边界" tabindex="-1">5. 范围边界 <a class="header-anchor" href="#_5-范围边界" aria-label="Permalink to &quot;5. 范围边界&quot;">​</a></h2><h3 id="_5-1-功能范围" tabindex="-1">5.1 功能范围 <a class="header-anchor" href="#_5-1-功能范围" aria-label="Permalink to &quot;5.1 功能范围&quot;">​</a></h3><p>列出本阶段必须完成、可选和明确排除的任务。可选项不得影响核心验收。</p><h3 id="_5-2-数据范围" tabindex="-1">5.2 数据范围 <a class="header-anchor" href="#_5-2-数据范围" aria-label="Permalink to &quot;5.2 数据范围&quot;">​</a></h3><p>明确权威来源、时间范围、地域、分类、保留、删除和是否可用于评测或训练。能读取数据不等于有权用于所有目的。</p><h3 id="_5-3-集成范围" tabindex="-1">5.3 集成范围 <a class="header-anchor" href="#_5-3-集成范围" aria-label="Permalink to &quot;5.3 集成范围&quot;">​</a></h3><p>记录模型、身份、业务 API、知识库、通知和人工工作台，以及沙箱/生产凭据、所有者和失败降级。</p><h3 id="_5-4-运行范围" tabindex="-1">5.4 运行范围 <a class="header-anchor" href="#_5-4-运行范围" aria-label="Permalink to &quot;5.4 运行范围&quot;">​</a></h3><p>定义环境、预计用户、峰值、服务时间、地域、支持渠道和人工运营时段。一个 7×24 Agent 若只在工作日有人接管，交付承诺必须说明。</p><h2 id="_6-验收模型" tabindex="-1">6. 验收模型 <a class="header-anchor" href="#_6-验收模型" aria-label="Permalink to &quot;6. 验收模型&quot;">​</a></h2><p>验收不使用一个总分，而是分层门禁：</p><table tabindex="0"><thead><tr><th>层级</th><th>证明什么</th><th>典型证据</th></tr></thead><tbody><tr><td>功能</td><td>用户任务可完成</td><td>端到端场景、业务终态</td></tr><tr><td>质量</td><td>输出和轨迹达标</td><td>版本化评测集、误差分析</td></tr><tr><td>安全</td><td>权限和数据边界成立</td><td>威胁测试、审计记录</td></tr><tr><td>性能</td><td>目标负载满足 SLO</td><td>压测、Trace、容量报告</td></tr><tr><td>可靠性</td><td>故障可限制和恢复</td><td>故障注入、恢复演练</td></tr><tr><td>运营</td><td>有人能支持和纠正</td><td>Runbook、排班、人工队列</td></tr><tr><td>经济性</td><td>结果成本可接受</td><td>每成功任务成本、预算</td></tr></tbody></table><p>硬门禁如越权、泄密和不可恢复副作用，不得被其他高分平均抵消。</p><h2 id="_7-可执行验收标准" tabindex="-1">7. 可执行验收标准 <a class="header-anchor" href="#_7-可执行验收标准" aria-label="Permalink to &quot;7. 可执行验收标准&quot;">​</a></h2><h3 id="_7-1-标准结构" tabindex="-1">7.1 标准结构 <a class="header-anchor" href="#_7-1-标准结构" aria-label="Permalink to &quot;7.1 标准结构&quot;">​</a></h3><p>每项标准包含对象、场景、数据、测量、阈值、证据、负责人和失败处置。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对象：高风险退款建议</span></span>
<span class="line"><span>数据：refund-critical-v5 的 300 个案例</span></span>
<span class="line"><span>测量：关键事实准确率、禁止工具调用</span></span>
<span class="line"><span>阈值：准确率 &gt;= 99%；禁止调用 = 0</span></span>
<span class="line"><span>证据：eval-run-2026-08-01-03 + 失败样本报告</span></span>
<span class="line"><span>负责人：售后产品负责人、应用安全负责人</span></span>
<span class="line"><span>失败：阻止发布；修复后全量重跑</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>阈值只是示例，真实标准由业务损失、基线、样本量和风险共同确定。</p><h3 id="_7-2-成功与失败-oracle" tabindex="-1">7.2 成功与失败 Oracle <a class="header-anchor" href="#_7-2-成功与失败-oracle" aria-label="Permalink to &quot;7.2 成功与失败 Oracle&quot;">​</a></h3><p>结构化任务优先使用业务终态、Schema 和不变量；开放输出使用 Rubric、Judge 与人工校准。模型说“已完成”不能作为动作成功 Oracle。</p><h3 id="_7-3-统计证据" tabindex="-1">7.3 统计证据 <a class="header-anchor" href="#_7-3-统计证据" aria-label="Permalink to &quot;7.3 统计证据&quot;">​</a></h3><p>报告样本数、Slice、分布和不确定性。20 个案例全过不足以证明 99.9% 目标；证据不足应标记“未证明”，不是默认通过。</p><h3 id="_7-4-非功能标准" tabindex="-1">7.4 非功能标准 <a class="header-anchor" href="#_7-4-非功能标准" aria-label="Permalink to &quot;7.4 非功能标准&quot;">​</a></h3><p>性能标准写 p95/p99 和负载环境；恢复标准写故障、RTO/RPO；成本写每成功任务；人工运营写积压与响应时间。</p><h2 id="_8-验收数据集" tabindex="-1">8. 验收数据集 <a class="header-anchor" href="#_8-验收数据集" aria-label="Permalink to &quot;8. 验收数据集&quot;">​</a></h2><h3 id="_8-1-来源" tabindex="-1">8.1 来源 <a class="header-anchor" href="#_8-1-来源" aria-label="Permalink to &quot;8.1 来源&quot;">​</a></h3><p>组合真实脱敏流量、专家案例、历史缺陷、合成变体和安全对抗样本。只用团队自己设计的理想问题会高估质量。</p><h3 id="_8-2-划分" tabindex="-1">8.2 划分 <a class="header-anchor" href="#_8-2-划分" aria-label="Permalink to &quot;8.2 划分&quot;">​</a></h3><p>开发集用于迭代，验证集用于选择，锁定测试集用于最终验收。按用户、文档或任务族分组切分，防止近重复泄漏。</p><h3 id="_8-3-版本" tabindex="-1">8.3 版本 <a class="header-anchor" href="#_8-3-版本" aria-label="Permalink to &quot;8.3 版本&quot;">​</a></h3><p>数据集、Rubric、参考事实和评分器都要版本化。验收结果绑定应用、Prompt、模型、工具、索引和配置版本。</p><h3 id="_8-4-所有权" tabindex="-1">8.4 所有权 <a class="header-anchor" href="#_8-4-所有权" aria-label="Permalink to &quot;8.4 所有权&quot;">​</a></h3><p>业务专家负责事实与口径，安全团队负责对抗集，工程团队负责可运行性，质量负责人负责数据流程。任何单一团队都不应自行定义并批准全部标准。</p><h2 id="_9-里程碑与阶段验收" tabindex="-1">9. 里程碑与阶段验收 <a class="header-anchor" href="#_9-里程碑与阶段验收" aria-label="Permalink to &quot;9. 里程碑与阶段验收&quot;">​</a></h2><h3 id="_9-1-discovery" tabindex="-1">9.1 Discovery <a class="header-anchor" href="#_9-1-discovery" aria-label="Permalink to &quot;9.1 Discovery&quot;">​</a></h3><p>证明任务、数据、风险和基线存在，识别无法自动化的边界。输出范围草案和技术风险实验，不承诺生产质量。</p><h3 id="_9-2-prototype" tabindex="-1">9.2 Prototype <a class="header-anchor" href="#_9-2-prototype" aria-label="Permalink to &quot;9.2 Prototype&quot;">​</a></h3><p>证明核心任务技术可行，使用受控数据和替身。不能用原型成功替代安全、容量和恢复验收。</p><h3 id="_9-3-pilot" tabindex="-1">9.3 Pilot <a class="header-anchor" href="#_9-3-pilot" aria-label="Permalink to &quot;9.3 Pilot&quot;">​</a></h3><p>在有限真实用户、权限和流量下验证质量、交互、运营与成本。Pilot 有明确开始、停止、回退和扩容标准。</p><h3 id="_9-4-general-availability" tabindex="-1">9.4 General Availability <a class="header-anchor" href="#_9-4-general-availability" aria-label="Permalink to &quot;9.4 General Availability&quot;">​</a></h3><p>全部发布门禁、支持责任、监控、恢复和生命周期管理到位。GA 不是“让所有用户看见开关”。</p><h2 id="_10-责任与签字" tabindex="-1">10. 责任与签字 <a class="header-anchor" href="#_10-责任与签字" aria-label="Permalink to &quot;10. 责任与签字&quot;">​</a></h2><p>使用 RACI 或同类责任矩阵明确：业务结果、产品范围、架构、数据、模型评测、安全、发布、值班和最终 Go/No-Go。签字表示对应证据已审查，不是把所有风险转给签字人。</p><p>未解决风险记录影响、缓解、所有者、到期日和有权接受者。高风险缺陷不能用“后续优化”模糊处理。</p><h2 id="_11-变更控制" tabindex="-1">11. 变更控制 <a class="header-anchor" href="#_11-变更控制" aria-label="Permalink to &quot;11. 变更控制&quot;">​</a></h2><p>新增工具、数据源、用户群、自动化等级、模型、地域或业务动作都可能改变范围和风险，应重新评估验收标准。变更记录说明原因、受影响标准、数据集和是否需要重新批准。</p><p>范围冻结不是禁止学习，而是避免未评估变更悄悄进入交付版本。变更可进入下一个里程碑或通过正式例外处理。</p><h2 id="_12-填写后的范围摘要" tabindex="-1">12. 填写后的范围摘要 <a class="header-anchor" href="#_12-填写后的范围摘要" aria-label="Permalink to &quot;12. 填写后的范围摘要&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目：售后退款建议 Agent v1</span></span>
<span class="line"><span>业务结果：专员处理时间中位数从 12 分钟降至 6 分钟</span></span>
<span class="line"><span>用户：境内售后专员；不面向终端客户</span></span>
<span class="line"><span>包含：政策问答、订单事实查询、退款建议草稿</span></span>
<span class="line"><span>排除：自动退款、海外订单、法律争议处理</span></span>
<span class="line"><span>数据：订单只读 API、版本化退款政策库</span></span>
<span class="line"><span>自动化：建议自动；创建退款必须专员确认</span></span>
<span class="line"><span>质量门禁：关键事实 &gt;= 99%；引用准确 &gt;= 98%</span></span>
<span class="line"><span>安全门禁：跨租户访问与未确认写操作 = 0</span></span>
<span class="line"><span>性能：首反馈 p95 &lt;= 2s；建议完成 p95 &lt;= 20s</span></span>
<span class="line"><span>Pilot：30 名专员、4 周、10% 工单；可一键回退旧流程</span></span>
<span class="line"><span>责任：售后负责人验收业务；安全负责人验收权限；平台负责运行</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="_13-常见误区" tabindex="-1">13. 常见误区 <a class="header-anchor" href="#_13-常见误区" aria-label="Permalink to &quot;13. 常见误区&quot;">​</a></h2><ol><li><strong>把模型能力当项目范围</strong>：用户任务和业务终态缺失。</li><li><strong>验收标准是“回答基本正确”</strong>：没有数据、阈值和负责人。</li><li><strong>只验收正常路径</strong>：不确定、权限和依赖失败未定义。</li><li><strong>Pilot 没有退出条件</strong>：试点长期停留在灰色生产状态。</li><li><strong>发布前不断加能力</strong>：风险和评测没有同步更新。</li></ol><h2 id="_14-范围评审清单" tabindex="-1">14. 范围评审清单 <a class="header-anchor" href="#_14-范围评审清单" aria-label="Permalink to &quot;14. 范围评审清单&quot;">​</a></h2><ul><li>业务结果是否有当前基线和目标；</li><li>用户、任务、Slice、数据和环境是否明确；</li><li>建议、草稿、确认执行和禁止能力是否分开；</li><li>功能、质量、安全、性能、可靠性、运营和成本是否都有证据；</li><li>硬门禁是否不能被平均分抵消；</li><li>验收数据和全部运行版本是否可追踪；</li><li>每项风险与标准是否有负责人和失败处置；</li><li>变更是否会触发范围和验收复查。</li></ul><p>范围与验收标准的作用，是让项目在开始时就知道如何结束。只有“完成”能够由共同认可的证据判定，Agent 项目才不会停留在永远可演示、永远未交付的状态。</p>`,97)])])}const u=e(l,[["render",i]]);export{b as __pageData,u as default};
